#include <stdio.h>
int sum(const int *a,int n){int s=0;for(int i=0;i<n;i++)s+=a[i];return s;}
int main(void){int a[]={2,4,6};int n=0;while(n<3)n++;do{n--;}while(n>3);printf("%d %d\n",sum(a,3),n);return 0;}

#include <stdio.h>
#include <string.h>
struct Item{int value;char name[16];};
int main(void){struct Item a={7,"pocket"};struct Item *p=&a;char b[32];strcpy(b,p->name);strcat(b," C");p->value+=2;printf("%s %d %lu\n",b,a.value,(unsigned long)strlen(b));return 0;}
